// src/lib/mcp/tools/list-projects.ts
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.25.1";
import { z } from "npm:zod@^3.25.76";
var list_projects_default = defineTool4({
  name: "list_projects",
  title: "List projects",
  description: "List the public portfolio projects, documents, and graphic design work. Optionally filter by a keyword.",
  inputSchema: {
    query: z.string().trim().optional().describe("Optional keyword to filter projects and designs by title or description.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query }) => {
    const q = query?.toLowerCase();
    const matchedProjects = q ? projects.filter((p) => `${p.title} ${p.description}`.toLowerCase().includes(q)) : projects;
    const matchedDesigns = q ? designs.filter((d) => d.toLowerCase().includes(q)) : designs;
    const result = { projects: matchedProjects, designs: matchedDesigns };
    return {
      content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
      structuredContent: result
    };
  }
});

